From a6610fb8f3be549a2bc8277a2609d82401c7873e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 23:04:43 +0100
Subject: [PATCH] shell/scripting: make widget geometry settable on the desktop

Assigning a widget's geometry from desktop scripts was silently ignored,
as the setter was an empty stub. It now moves and resizes the widget in
the desktop layout, and throws an error for widgets outside the desktop.

BUG: 362511
---
 .../appletslayout.cpp                         | 13 ++++++++++
 .../containmentlayoutmanager/appletslayout.h  |  1 +
 shell/scripting/widget.cpp                    | 24 ++++++++++++-------
 3 files changed, 30 insertions(+), 8 deletions(-)

diff --git a/components/containmentlayoutmanager/appletslayout.cpp b/components/containmentlayoutmanager/appletslayout.cpp
index a3cee50db3..08b8b5c894 100644
--- a/components/containmentlayoutmanager/appletslayout.cpp
+++ b/components/containmentlayoutmanager/appletslayout.cpp
@@ -492,6 +492,19 @@ void AppletsLayout::releaseSpace(ItemContainer *item)
     m_layoutManager->releaseSpace(item);
 }

+void AppletsLayout::setAppletGeometry(Plasma::Applet *applet, const QRectF &geometry)
+{
+    AppletContainer *container = m_containerForApplet.value(applet);
+    if (!container) {
+        return;
+    }
+
+    container->setPosition(QPointF(geometry.x() - container->leftPadding(), geometry.y() - container->topPadding()));
+    container->setSize(QSizeF(geometry.width() + container->leftPadding() + container->rightPadding(),
+                              geometry.height() + container->topPadding() + container->bottomPadding()));
+    m_layoutManager->positionItemAndAssign(container);
+}
+
 void AppletsLayout::geometryChange(const QRectF &newGeometry, const QRectF &oldGeometry)
 {
     // Ignore completely moves without resize
diff --git a/components/containmentlayoutmanager/appletslayout.h b/components/containmentlayoutmanager/appletslayout.h
index 3964a02b71..5420bbf713 100644
--- a/components/containmentlayoutmanager/appletslayout.h
+++ b/components/containmentlayoutmanager/appletslayout.h
@@ -164,6 +164,7 @@ public:
     Q_INVOKABLE void positionItem(ItemContainer *item);
     Q_INVOKABLE void restoreItem(ItemContainer *item);
     Q_INVOKABLE void releaseSpace(ItemContainer *item);
+    Q_INVOKABLE void setAppletGeometry(Plasma::Applet *applet, const QRectF &geometry);

 Q_SIGNALS:
     /**
diff --git a/shell/scripting/widget.cpp b/shell/scripting/widget.cpp
index 1cafd1c826..7cc82cfd7d 100644
--- a/shell/scripting/widget.cpp
+++ b/shell/scripting/widget.cpp
@@ -11,6 +11,8 @@
 #include <QMetaEnum>
 #include <QQuickItem>

+#include <KLocalizedString>
+
 #include <Plasma/Applet>
 #include <Plasma/Containment>
 #include <Plasma/Corona>
@@ -168,14 +170,20 @@ QJSValue Widget::geometry() const

 void Widget::setGeometry(const QJSValue &geometry)
 {
-    Q_UNUSED(geometry)
-    /*if (d->applet) {
-        d->applet->setGeometry(geometry);
-        KConfigGroup cg = d->applet->config().parent();
-        if (cg.isValid()) {
-            cg.writeEntry("geometry", geometry);
-        }
-    }*/
+    QQuickItem *appletItem = PlasmaQuick::AppletQuickItem::itemForApplet(d->applet);
+    QQuickItem *container = appletItem ? appletItem->parentItem() : nullptr;
+    auto layout = container ? qobject_cast<QQuickItem *>(container->property("layout").value<QObject *>()) : nullptr;
+
+    if (!layout) {
+        engine()->throwError(i18n("The geometry can only be set for widgets on the desktop"));
+        return;
+    }
+
+    const QRectF rect(geometry.property(QStringLiteral("x")).toNumber(),
+                      geometry.property(QStringLiteral("y")).toNumber(),
+                      geometry.property(QStringLiteral("width")).toNumber(),
+                      geometry.property(QStringLiteral("height")).toNumber());
+    QMetaObject::invokeMethod(layout, "setAppletGeometry", Q_ARG(Plasma::Applet *, d->applet.data()), Q_ARG(QRectF, layout->mapRectFromScene(rect)));
 }

 void Widget::showConfigurationInterface()
